Here’s a straightforward approach:

```javascript
function removeDuplicates(arr) {
  if (Array.isArray(arr)) {
    const result = new Set(); // Use a Set for O(1) duplicates check
    for (const item of arr) {
      result.add(item);
    }
    return Array.from(result); // Convert back to array (not sorted)
  } else {
    throw new TypeError('Expected an array.');
  }
}

// Examples:
removeDuplicates([1, 2, 2, 3]);        // [1, 2, 3]
removeDuplicates(['a', 'b', 'c']);     // ['a', 'b', 'c']
```

Notes / alternatives based on desired order/behavior:

- **Preserve original order (no duplicates only):**  
  ```javascript
  const removeDuplicates = (arr) => {
    return [...new Set(arr)]; // Same as above in JS.
  };
  ```

- **Remove adjacent duplicates and preserve all others:**  
  ```javascript
  function removeAdjacentDupsArrary(arr) {
    const result = [];
    if (!Array.isArray(arr)) throw new TypeError(...);
    for (let i = 0; i < arr.length; i++) {
      const current = arr[i];
      const previous = result[result.length - 1] ?? null;
      if (previous === null || current !== previous) {
        result.push(current);
      }
    }
    return result;
  }

  removeAdjacentDupsArrary([1, 2, 2, 3]);   // [1, 2, 3]
  ```

